import verified from './youtubeVideos.json';

/**
 * Curated tutorial per built-in exercise (Master Plan v3 §3.3, D11).
 * Generated by `scripts/media/check-youtube.mjs`: every entry passed
 * YouTube's oEmbed check (public, embeddable) on `checkedAt` and was reviewed
 * as the exact movement. Never edited by hand.
 */
export interface CuratedVideo {
  videoId: string;
  title: string;
  channel: string;
  checkedAt: string;
}

export const CURATED_VIDEOS: Readonly<Record<string, CuratedVideo>> = verified as Record<string, CuratedVideo>;

export const curatedVideo = (exerciseId: string): CuratedVideo | null => CURATED_VIDEOS[exerciseId] ?? null;
